BEGIN;
DO $$ DECLARE owner uuid;other_user uuid;w uuid:=gen_random_uuid();c uuid:=gen_random_uuid();req uuid:=gen_random_uuid();n integer;blocked boolean:=false; BEGIN SELECT id INTO owner FROM public.profiles ORDER BY created_at LIMIT 1;SELECT id INTO other_user FROM public.profiles WHERE id<>owner ORDER BY created_at LIMIT 1;IF owner IS NULL OR other_user IS NULL THEN RAISE EXCEPTION 'Two existing profiles required';END IF;
INSERT INTO public.workspaces(id,name,kind,owner_id) VALUES(w,'AI acceptance temporary workspace','team',owner);
INSERT INTO public.workspace_members(workspace_id,user_id,role) VALUES(w,owner,'owner') ON CONFLICT(workspace_id,user_id) DO NOTHING;
PERFORM set_config('request.jwt.claim.sub',owner::text,true);SET LOCAL ROLE authenticated;
INSERT INTO public.ai_conversations(id,user_id,workspace_id,title) VALUES(c,owner,w,'AI acceptance');
UPDATE public.ai_conversations SET title='Renamed acceptance' WHERE id=c;
SELECT count(*) INTO n FROM public.ai_conversations WHERE id=c AND title='Renamed acceptance';IF n<>1 THEN RAISE EXCEPTION 'Owner rename failed';END IF;
BEGIN INSERT INTO public.ai_messages(conversation_id,sdk_id,role,parts) VALUES(c,'forged','assistant','[]');EXCEPTION WHEN insufficient_privilege THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'Client message forgery permitted';END IF;
RESET ROLE;
IF NOT public.begin_ai_request(req,c,owner) THEN RAISE EXCEPTION 'First request refused';END IF;IF public.begin_ai_request(gen_random_uuid(),c,owner) THEN RAISE EXCEPTION 'Duplicate request allowed';END IF;
INSERT INTO public.ai_messages(conversation_id,sdk_id,role,parts,request_id) VALUES(c,'verified','assistant','[{"type":"text","text":"Acceptance response"}]',req);
PERFORM set_config('request.jwt.claim.sub',other_user::text,true);SET LOCAL ROLE authenticated;
SELECT count(*) INTO n FROM public.ai_conversations WHERE id=c;IF n<>0 THEN RAISE EXCEPTION 'Other user sees conversation';END IF;
SELECT count(*) INTO n FROM public.ai_messages WHERE conversation_id=c;IF n<>0 THEN RAISE EXCEPTION 'Other user sees messages';END IF;
blocked:=false;BEGIN INSERT INTO public.ai_conversations(user_id,workspace_id,title) VALUES(other_user,w,'Unauthorized workspace');EXCEPTION WHEN insufficient_privilege THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'Unauthorized workspace accepted';END IF;
RESET ROLE;
PERFORM set_config('request.jwt.claim.sub',owner::text,true);SET LOCAL ROLE authenticated;
DELETE FROM public.ai_conversations WHERE id=c;SELECT count(*) INTO n FROM public.ai_messages WHERE conversation_id=c;IF n<>0 THEN RAISE EXCEPTION 'Deleted conversation retains visible messages';END IF;
RESET ROLE;END $$;
ROLLBACK;